source='''def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    counts = {"up": 0, "down": 0}
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 2 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for ny, nx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0 <= ny < h and 0 <= nx < w and grid[ny][nx] == 2 and (ny,nx) not in seen:
                        seen.add((ny,nx))
                        stack.append((ny,nx))
            minr, maxr = min(y for y,x in cells), max(y for y,x in cells)
            minc, maxc = min(x for y,x in cells), max(x for y,x in cells)
            shape = {(y-minr, x-minc) for y,x in cells}
            if maxr-minr == 1 and maxc-minc == 2 and len(cells) == 4:
                if shape == {(0,1),(1,0),(1,1),(1,2)}:
                    counts["up"] += 1
                elif shape == {(0,0),(0,1),(0,2),(1,1)}:
                    counts["down"] += 1
    out = [[0]*6 for _ in range(3)]
    slots = ((0,0),(2,0),(0,2),(2,2))
    for n, color, offset in ((counts["up"],3,0),(counts["down"],1,3)):
        for r,c in slots[:min(n,4)]:
            out[r][c+offset] = color
    return out
